(function () {
  'use strict';

  /* ---------- Fade-up reveal ----------
     Any element with [data-fade] starts hidden (.dd-fade in CSS) and gets
     .is-visible the first time it crosses into view. */
  var fadeEls = document.querySelectorAll('[data-fade]');
  if (fadeEls.length) {
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            io.unobserve(entry.target);
          }
        });
      }, { threshold: 0, rootMargin: '0px 0px -10px 0px' });
      fadeEls.forEach(function (el) { io.observe(el); });
    } else {
      // No IntersectionObserver support — just show everything.
      fadeEls.forEach(function (el) { el.classList.add('is-visible'); });
    }
  }

  /* ---------- Custom cursor ----------
     Disabled — the site uses the normal system cursor everywhere. */

  /* ---------- Tracking hooks ----------
     [data-track] on links/buttons and [data-conversion] on a landed-on
     section are lightweight, provider-agnostic hooks: if the site later
     wires up an analytics tool that reads window.dataLayer (GA4, GTM,
     etc.), these already fire the right events. With nothing installed
     they're harmless no-ops. */
  function pushEvent(name, detail) {
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push(Object.assign({ event: name }, detail || {}));
  }

  document.querySelectorAll('[data-track]').forEach(function (el) {
    el.addEventListener('click', function () {
      pushEvent('dd_track', { label: el.getAttribute('data-track') });
    });
  });

  var conversionEl = document.querySelector('[data-conversion]');
  if (conversionEl) {
    pushEvent('dd_conversion', { label: conversionEl.getAttribute('data-conversion') });
  }
})();


